@app.context_processor
def inject_globals():
    return {"site_name": "Физика 9", "current_year": 2026}

@app.route("/")
def index():
    return render_template("index.html", phenomena=PHENOMENA[:6], terms_count=len(TERMS),
                           formulas_count=len(FORMULAS), phenomena_count=len(PHENOMENA))

@app.route("/phenomena")
def phenomena():
    q = request.args.get("q", "").strip().lower()
    category = request.args.get("category", "Все")
    categories = ["Все"] + sorted({p["category"] for p in PHENOMENA})
    results = [p for p in PHENOMENA if
               (not q or q in p["title"].lower() or q in p["term"].lower() or q in p["tags"].lower())
               and (category == "Все" or p["category"] == category)]
    return render_template("phenomena.html", phenomena=results, categories=categories, q=q, selected_category=category)

@app.route("/phenomena/<slug>")
def phenomenon_detail(slug):
    item = next((p for p in PHENOMENA if p["id"] == slug), None)
    if item is None:
        abort(404)
    return render_template("phenomenon_detail.html", item=item)

@app.route("/terms")
def terms():
    q = request.args.get("q", "").strip().lower()
    results = [(name, definition) for name, definition in TERMS if not q or q in name.lower() or q in definition.lower()]
    return render_template("terms.html", terms=results, q=q)

@app.route("/formulas")
def formulas():
    q = request.args.get("q", "").strip().lower()
    category = request.args.get("category", "Все")
    categories = ["Все"] + sorted({f[4] for f in FORMULAS})
    results = [f for f in FORMULAS if (not q or any(q in str(x).lower() for x in f))
               and (category == "Все" or f[4] == category)]
    return render_template("formulas.html", formulas=results, q=q, categories=categories, selected_category=category)

@app.route("/cheatsheets")
def cheatsheets():
    return render_template("cheatsheets.html", cheatsheets=CHEATSHEETS)

@app.route("/quiz", methods=["GET", "POST"])
def quiz():
    result = None
    if request.method == "POST":
        answers = request.form
        correct = sum(1 for i, item in enumerate(QUIZ) if answers.get(f"q{i}") == str(item["answer"]))
        result = {"correct": correct, "total": len(QUIZ), "percent": round(correct / len(QUIZ) * 100)}
    return render_template("quiz.html", questions=QUIZ, result=result)

@app.errorhandler(404)
def not_found(error):
    return render_template("404.html"), 404

if __name__ == "__main__":
    app.run(debug=True)
